-- ==========================================
-- 🚄 전국 28개 노선 및 800+ 역/인접 그래프 마스터 시드
-- ==========================================

-- 1. LINES 테이블 인서트 / 업데이트
ON CONFLICT (id) DO UPDATE SET line_name = EXCLUDED.line_name, color_code = EXCLUDED.color_code;

-- 2. STATIONS 테이블 인서트
ON CONFLICT (id) DO UPDATE SET station_name = EXCLUDED.station_name;

-- 3. STATION_CONNECTIONS 테이블 인서트
ON CONFLICT ON CONSTRAINT unique_connection DO NOTHING;
